// TheHive alert per ALERT-FORMAT §1-§5, from the canonical alert and lib-config.
const { canonical: c, config: cfg, context } = $input.first().json;
const source = cfg.source_by_rule_id[c.rule.id] ?? cfg.source_default;
let severity = cfg.severity_default;
for (const r of cfg.severity_by_level) {
  if (c.rule.level >= r.min && c.rule.level <= r.max) severity = r.severity;
}
if (cfg.severity_raise_for_criticality.includes(cfg.asset_criticality)) severity = Math.min(4, severity + 1);
const groups = c.rule.groups;
// Case template chosen by the router (lib-route-alert, N8N-1.3); a caller
// without a route gets the routing table's default row.
const route = $input.first().json.route;
const caseTemplate = route?.case_template ?? cfg.routing.rows.find((r) => r.default).case_template;
// The host the alert is about (ALERT-FORMAT §1, answer F): the agent, or on a
// syslog alert (agent 000) the device, predecoder.hostname, else its address
// (location). Used for the title, the agent: tag and wazuh-agent-name.
const hostName = c.host.name ?? c.host.ip ?? c.agent.name;
const tags = [...new Set(['wazuh', `rule:${c.rule.id}`, `agent:${hostName}`,
  ...c.rule.mitre_ids.map((t) => `attack.${t.toLowerCase()}`), ...groups])];
// FIM title (ALERT-FORMAT §1, X-44): Wazuh's FIM descriptions don't name the
// file (553 is "File deleted."), so a syscheck alert adds syscheck.path. The
// path can be attacker-chosen: cut to title_caps.syscheck_path_max_chars
// characters with "…" at the cut, control characters replaced.
let titleText = c.rule.description;
if (groups.includes(cfg.fim.group) && c.syscheck.path) {
  const max = cfg.title_caps.syscheck_path_max_chars;
  const chars = Array.from(c.syscheck.path.replace(/[\u0000-\u001f\u007f]/g, '?'));
  titleText += ' ' + (chars.length > max ? chars.slice(0, max - 1).join('') + '…' : chars.join(''));
}

// Observables come from lib-extract-observables (N8N-2.3); its n8n-only
// fields (asox: range flag, sources) stay out of TheHive's body. `message`
// (the observable's description) is set by lib-misp-warninglist (answer G).
const ex = $input.first().json.extraction;
if (!ex || !Array.isArray(ex.observables)) throw new Error('lib-thehive-upsert-alert needs the lib-extract-observables output as `extraction`');
const observables = ex.observables.map(({ dataType, data, tags, ioc, message }) => (
  message ? { dataType, data, tags, ioc, message } : { dataType, data, tags, ioc }));
const skipped = ex.skipped;
const prefix = cfg.observable_ranges.tag_prefix;
const observableSummary = ex.observables.map((o) => `${o.dataType}:${o.data}`
  + o.tags.filter((t) => t.startsWith(prefix)).map((t) => ` (${t})`).join(''));

const esc = (v) => String(v).replace(/\|/g, '\\|').replace(/\r?\n/g, ' ');
const rows = [
  ['Rule', `${c.rule.id}: ${c.rule.description}`],
  ['Level', c.rule.level],
  c.host.source === 'syslog'
    ? ['Host', `${hostName} (syslog from ${c.host.ip}; agent ${c.agent.name} (${c.agent.id}))`]
    : ['Agent', `${c.agent.name} (${c.agent.id})`],
  ['MITRE', c.rule.mitre_ids.join(', ') || 'none'],
  ['Wazuh alert ID', c.wazuh_alert_id],
  ['Time', c.timestamp],
  // sudo (5404): what was run, where, from which terminal (answer A).
  ...(c.sudo ? [['sudo command', c.sudo.command], ['sudo working directory', c.sudo.pwd], ['sudo TTY', c.sudo.tty]] : [])
    .filter(([, v]) => v !== null),
];
let description = '| Field | Value |\n|---|---|\n' + rows.map(([k, v]) => `| ${k} | ${esc(v)} |`).join('\n');
if (c.full_log) {
  const longest = Math.max(0, ...[...c.full_log.matchAll(/`+/g)].map((m) => m[0].length));
  const fence = '`'.repeat(Math.max(3, longest + 1));
  description += `\n\n${fence}\n${c.full_log}\n${fence}`;
}
// Array form, as in TheHive's reference script; which form TheHive 5.7.6
// fills can only be checked once the fields exist (T1.3).
const customFields = [
  ['wazuh-alert-id', c.wazuh_alert_id],
  ['wazuh-rule-id', c.rule.id_int],
  ['wazuh-rule-level', c.rule.level],
  ['wazuh-agent-name', hostName],
  ['mitre-technique', c.rule.mitre_ids[0] ?? null],
  ['asset-criticality', cfg.asset_criticality],
  ['playbook', context.playbook],
  ['n8n-execution-id', String(context.n8n_execution_id)],
].filter(([, v]) => v !== null && v !== undefined).map(([name, value]) => ({ name, value }));

return [{ json: {
  body: {
    type: cfg.thehive_alert_type, source, sourceRef: c.wazuh_alert_id,
    title: `${titleText} (${hostName})`, description,
    severity, tlp: cfg.tlp, pap: cfg.pap, date: c.date_ms, tags, caseTemplate, customFields, observables,
  },
  skipped_observables: skipped,
  observable_summary: observableSummary,
  context,
  wazuh_alert_id: c.wazuh_alert_id,
} }];

// 201 = created; 400 CreateError "already exists" = already done (duplicate
// sourceRef, ALERT-TO-THEHIVE.md §2); anything else = failed.
const r = $input.first().json;
const body = r.body ?? {};
const sent = $('Build alert').first().json.body;
if (r.statusCode === 201) {
  const warnings = [];
  if (sent.caseTemplate && !body.caseTemplate) warnings.push(`caseTemplate ${sent.caseTemplate} dropped by TheHive (unknown there: entities/ not loaded, T1.3, or a routing row naming a template TheHive doesn't have)`);
  if (sent.customFields.length > 0 && (body.customFields ?? []).length === 0) warnings.push('customFields dropped by TheHive (fields not loaded: entities/, T1.3)');
  return [{ json: { outcome: 'created', attempts: r.attempts, thehive_alert_id: body._id, created_at: body._createdAt ?? null, returned_custom_fields: (body.customFields ?? []).length, warnings } }];
}
if (r.statusCode === 400 && body.type === 'CreateError' && /already exists/.test(body.message ?? '')) {
  // A retried create whose first call timed out may have created it after all.
  return [{ json: { outcome: 'duplicate', message: body.message, after_retry: r.attempts > 1 } }];
}
return [{ json: { outcome: 'failed', http_status: r.statusCode, stage: 'Create TheHive alert',
  message: `HTTP ${r.statusCode}: ${typeof r.body === 'string' ? r.body : JSON.stringify(r.body)}`.slice(0, 1000),
  payload: sent, attempts: r.attempts } }];

const r = $input.first().json;
const b = $('Build alert').first().json;
return [{ json: {
  ok: true, outcome: 'created', duplicate: false, attempts: r.attempts, thehive_alert_id: r.thehive_alert_id,
  // TheHive's _createdAt (ms): C11's t_alert (N8N-2.9).
  created_at: r.created_at ?? null,
  wazuh_alert_id: b.wazuh_alert_id, source: b.body.source, severity: b.body.severity,
  case_template: b.body.caseTemplate, tags: b.body.tags,
  observables: b.observable_summary,
  skipped_observables: b.skipped_observables, warnings: r.warnings,
} }];

// Already done: return the existing alert; nothing is created or repeated.
const r = $input.first().json;
const b = $('Build alert').first().json;
const found = r.statusCode === 200 && Array.isArray(r.body) ? r.body : [];
if (found.length !== 1) {
  throw new Error(`TheHive refused a duplicate of ${b.body.source}:${b.body.sourceRef} but the lookup returned HTTP ${r.statusCode} with ${found.length} alert(s)`);
}
return [{ json: {
  ok: true, outcome: 'duplicate', duplicate: true,
  after_retry: $('Interpret create').first().json.after_retry === true, thehive_alert_id: found[0]._id,
  created_at: found[0]._createdAt ?? null,
  wazuh_alert_id: b.wazuh_alert_id, source: b.body.source, severity: found[0].severity,
  case_template: b.body.caseTemplate, tags: found[0].tags, observables: [], skipped_observables: [], warnings: [],
} }];

// Explicit lib-error input (N8N-2.5): keeps the Wazuh alert ID, which n8n's
// Error Trigger would not have. Handles both a failed HTTP status (item from
// the interpreting Code node) and a connection error (HTTP node error output).
const j = $input.first().json;
const ctx = (() => { const b = $('Build alert').first().json; return { context: b.context, wazuh_alert_id: b.wazuh_alert_id, thehive_alert_id: null, payload: b.body }; })();
const err = j.error;
const message = j.message ?? (typeof err === 'string' ? err : err?.message) ?? JSON.stringify(j).slice(0, 500);
return [{ json: {
  stage: 'thehive: ' + (j.stage ?? $prevNode.name),
  workflow: $workflow.name,
  execution_id: ctx.context?.n8n_execution_id ?? $execution.id,
  sub_execution_id: $execution.id,
  node: j.node ?? $prevNode.name,
  wazuh_alert_id: ctx.wazuh_alert_id ?? null,
  thehive_alert_id: ctx.thehive_alert_id ?? null,
  http_status: j.http_status ?? err?.httpCode ?? null,
  error_code: j.error_code ?? err?.code ?? err?.cause?.code ?? null,
  message,
  // Calls made (N8N-6.2); retry_exhausted = TheHive stayed unreachable or 5xx.
  attempts: j.attempts ?? null,
  retry_exhausted: j.retry_exhausted === true,
  // What was being sent, for a later replay (N8N-6.3): kept on every failure.
  payload: j.payload ?? ctx.payload ?? null,
} }];

// Handed to lib-error (parked there); the caller stops without further actions.
const e = $('Error input').first().json;
return [{ json: { ok: false, parked: true, stage: e.stage, http_status: e.http_status, message: e.message } }];

// THEHIVE_ENABLED=false: TheHive isn't deployed for this core (no cases node).
// Not an outage: nothing is sent, nothing is parked.
const j = $input.first().json;
return [{ json: {
  ok: false, skipped: true, outcome: 'skipped', reason: 'TheHive not configured',
  wazuh_alert_id: j.canonical?.wazuh_alert_id ?? null,
  enabled_source: j.config?.thehive?.enabled_source ?? null,
} }];

// Retry policy for TheHive calls (N8N-6.2; lib-config thehive_http): a
// connection error, a timeout or HTTP 5xx -> wait and call again; anything
// else (2xx, and 4xx, which a retry never fixes) -> passed on. A transient
// failure on the last call goes to lib-error with the number of calls.
const r = $input.first().json;
const policy = $('Called by a workflow').first().json.config.thehive_http;
const NODE = 'Create TheHive alert';
const attempt = $runIndex + 1; // this node runs once per call
const status = typeof r.statusCode === 'number' ? r.statusCode : null;
const thrown = r.error !== undefined && status === null; // HTTP node error output
const NETWORK = /ECONNREFUSED|ENOTFOUND|EAI_AGAIN|ETIMEDOUT|ECONNRESET|EHOSTUNREACH|ENETUNREACH|ECONNABORTED|timeout|timed out|socket hang up|connection cannot be established/i;
const transient = thrown ? NETWORK.test(JSON.stringify(r)) : status >= 500;
const calls = policy.retry_waits_s.length + 1;
if (transient && attempt < calls) {
  return [{ json: { decision: 'retry', stage: NODE, attempt, wait_s: policy.retry_waits_s[attempt - 1],
    reason: thrown ? 'connection error or timeout' : `HTTP ${status}` } }];
}
if (thrown || transient) {
  const e = r.error;
  const detail = thrown
    ? (typeof e === 'string' ? e : [e?.message, e?.description].filter(Boolean).join(': ') || JSON.stringify(r))
    : `HTTP ${status}: ${typeof r.body === 'string' ? r.body : JSON.stringify(r.body)}`;
  return [{ json: { decision: 'error', stage: NODE, node: NODE, attempts: attempt, retry_exhausted: transient,
    http_status: status, error_code: e?.code ?? e?.cause?.code ?? null,
    message: `${detail}`.slice(0, 1000) + (transient ? ` (${attempt} calls)` : '') } }];
}
return [{ json: { ...r, decision: 'response', attempts: attempt } }];

// Retry policy for TheHive calls (N8N-6.2; lib-config thehive_http): a
// connection error, a timeout or HTTP 5xx -> wait and call again; anything
// else (2xx, and 4xx, which a retry never fixes) -> passed on. A transient
// failure on the last call goes to lib-error with the number of calls.
const r = $input.first().json;
const policy = $('Called by a workflow').first().json.config.thehive_http;
const NODE = 'Find existing TheHive alert';
const attempt = $runIndex + 1; // this node runs once per call
const status = typeof r.statusCode === 'number' ? r.statusCode : null;
const thrown = r.error !== undefined && status === null; // HTTP node error output
const NETWORK = /ECONNREFUSED|ENOTFOUND|EAI_AGAIN|ETIMEDOUT|ECONNRESET|EHOSTUNREACH|ENETUNREACH|ECONNABORTED|timeout|timed out|socket hang up|connection cannot be established/i;
const transient = thrown ? NETWORK.test(JSON.stringify(r)) : status >= 500;
const calls = policy.retry_waits_s.length + 1;
if (transient && attempt < calls) {
  return [{ json: { decision: 'retry', stage: NODE, attempt, wait_s: policy.retry_waits_s[attempt - 1],
    reason: thrown ? 'connection error or timeout' : `HTTP ${status}` } }];
}
if (thrown || transient) {
  const e = r.error;
  const detail = thrown
    ? (typeof e === 'string' ? e : [e?.message, e?.description].filter(Boolean).join(': ') || JSON.stringify(r))
    : `HTTP ${status}: ${typeof r.body === 'string' ? r.body : JSON.stringify(r.body)}`;
  return [{ json: { decision: 'error', stage: NODE, node: NODE, attempts: attempt, retry_exhausted: transient,
    http_status: status, error_code: e?.code ?? e?.cause?.code ?? null,
    message: `${detail}`.slice(0, 1000) + (transient ? ` (${attempt} calls)` : '') } }];
}
return [{ json: { ...r, decision: 'response', attempts: attempt } }];
